"""Regression coverage for pre-evaluation of Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('value', [0, 1])
@pytest.mark.parametrize('locale', [None, 'fr_FR'])
def test_faker_decider_resolves_defaults(value, locale):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'pyint',
                locale=locale,
                min_value=factory.LazyFunction(lambda: value),
                max_value=value,
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    for result in ExampleFactory.create_batch(3):
        assert result['result'] == ('yes' if value else 'no')


def test_nested_maybe_decider():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == 'yes'


def test_overrides_apply_to_selected_declaration_not_decider():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('pyint', min_value=1, max_value=1),
            yes_declaration=factory.Faker('pyint', min_value=2, max_value=2),
            no_declaration=-1,
        )

    assert ExampleFactory(result__min_value=0, result__max_value=0)['result'] == 0
